/**
 * Syntax abstraction entry point:
 * Part of front-end processing of APIs.
 * <p/>
 * 1) Disambiguate item symbols and rewrite to either nonterminal,
 * keyword or token symbol
 * 2) Disambiguate nonterminal parameters (Not any more)
 * We need to support nonterminal parameters to express
 * desugaring of Fortress comprehensions?
 * In order to support it,
 * the parameters should be handled by TemplateVarRewriter.identifierLoop
 * and Transform should handle it appropriately.
 * 3) Remove whitespace where indicated by no-whitespace symbols
 * 4) Rewrite escaped symbols
 * 5) Desugar extensions: fill in unmentioned imported grammars
 * and collect multiple extensions of same nonterminal together.
 * 6) Name transformers
 * 7) Parse pretemplates and replace with real templates
 * 8) Well-formedness check on template gaps (???)
 */
public class GrammarRewriter {

    public static Collection<Api> rewriteApis(Map<APIName, ApiIndex> map, GlobalEnvironment env) {
        initializeGrammarIndexExtensions(map.values(), env.apis().values());

        List<Api> apis = new ArrayList<Api>();
        for (ApiIndex apii : map.values()) {
            //            Nodes.printNode(apii.ast(), "before-grammar-rewrite.");
            apis.add((Api) apii.ast());
        }

        // Steps 1-6
        List<Api> results1 = rewritePatterns(apis, env);

        // Step 7
        List<Api> results2 = parseTemplates(results1, env);

        return results2;
    }

    private static List<Api> rewritePatterns(List<Api> apis, GlobalEnvironment env) {
        List<Api> results = new ArrayList<Api>();
        List<StaticError> allErrors = new ArrayList<StaticError>();

        for (Api api : apis) {
            //             Nodes.printNode(api, "before-rewritePatterns.");
            List<StaticError> errors = new ArrayList<StaticError>();

            // 1) Disambiguate item symbols and rewrite to either nonterminal,
            //    keyword or token symbol
            api = (Api) api.accept(new ItemDisambiguator(env, errors));
            //             Nodes.printNode(api, "after-ItemDisambiguator.");
            // 2) Disambiguate nonterminal parameters
            // No longer done.

            // 3) Remove whitespace where instructed by non-whitespace symbols
            if (errors.isEmpty()) api = (Api) api.accept(new WhitespaceElimination());
            //             Nodes.printNode(api, "after-WhitespaceElimination.");
            // 4) Rewrite escaped characters
            if (errors.isEmpty()) api = (Api) api.accept(new EscapeRewriter());
            //             Nodes.printNode(api, "after-EscapeRewriter.");
            // 5) Desugar extensions
            if (errors.isEmpty()) api = (Api) api.accept(new ExtensionDesugarer(env, errors));
            //             Nodes.printNode(api, "after-ExtensionDesugarer.");
            // 6) Rewrite transformer names
            if (errors.isEmpty()) api = (Api) api.accept(new RewriteTransformerNames());
            //             Nodes.printNode(api, "after-RewriteTransformerNames.");

            if (errors.isEmpty()) {
                results.add(api);
            } else {
                allErrors.addAll(errors);
            }
            //             Nodes.printNode(api, "after-rewritePatterns.");
        }


        if (allErrors.isEmpty()) {
            return results;
        } else {
            throw new MultipleStaticError(allErrors);
        }
    }

    private static List<Api> parseTemplates(List<Api> apis, GlobalEnvironment env) {
        Collection<ApiIndex> apiIndexes = buildApiIndexesOnly(apis, env);
        NTEnv ntEnv = buildNTEnv(apiIndexes, env);

        List<Api> results = new ArrayList<Api>();
        for (final ApiIndex api : apiIndexes) {
            //            Nodes.printNode(api.ast(), "before-parseTemplates.");
            results.add(TemplateParser.parseTemplates(api, ntEnv));
            //            Nodes.printNode(api.ast(), "after-parseTemplates.");
        }
        return results;
    }

    private static Collection<ApiIndex> buildApiIndexesOnly(Collection<Api> apis, GlobalEnvironment env) {
        IndexBuilder.ApiResult apiN = IndexBuilder.buildApis(apis, env, System.currentTimeMillis());
        return apiN.apis().values();
    }

    private static NTEnv buildNTEnv(Collection<ApiIndex> apis, GlobalEnvironment env) {
        Map<String, GrammarIndex> grammars = initializeGrammarIndexExtensions(apis, env.apis().values());
        return EnvFactory.makeNTEnv(grammars.values());
    }

    private static Map<String, GrammarIndex> initializeGrammarIndexExtensions(Collection<ApiIndex> apis,
                                                                              Collection<ApiIndex> moreApis) {
        Map<String, GrammarIndex> grammars = new HashMap<String, GrammarIndex>();

        for (ApiIndex a2 : moreApis) {
            for (Entry<String, GrammarIndex> e : a2.grammars().entrySet()) {
                grammars.put(e.getKey(), e.getValue());
                Debug.debug(Debug.Type.SYNTAX, 3, "Add grammar ", e.getKey(), " to ", e.getValue());
            }
        }
        for (ApiIndex a1 : apis) {
            for (Entry<String, GrammarIndex> e : a1.grammars().entrySet()) {
                grammars.put(e.getKey(), e.getValue());
                Debug.debug(Debug.Type.SYNTAX, 3, "Add grammar ", e.getKey(), " to ", e.getValue());
            }
        }
        for (ApiIndex a1 : apis) {
            for (Entry<String, GrammarIndex> e : a1.grammars().entrySet()) {
                GrammarDecl og = e.getValue().ast();
                List<GrammarIndex> ls = new LinkedList<GrammarIndex>();
                for (Id n : og.getExtendsClause()) {
                    GrammarIndex index = grammars.get(n.getText());
                    if (index == null){
                        throw new MacroError("Could not find grammar " + n + " in the extends clause of " + og);
                    }
                    ls.add(index);
                }
                Debug.debug(Debug.Type.SYNTAX, 3, "Grammar ", e.getKey(), " extends ", ls);
                e.getValue().setExtended(ls);
            }
        }
        return grammars;
    }
}

import com.sun.fortress.syntax_abstractions.rats.RatsUtil;
import com.sun.fortress.useful.Debug;
import com.sun.fortress.useful.Files;
import com.sun.fortress.useful.Useful;
import edu.rice.cs.plt.tuple.Option;
import xtc.parser.ParseError;
import xtc.parser.ParserBase;
import xtc.parser.SemanticValue;

import java.io.BufferedReader;
import java.io.IOException;
import java.lang.reflect.Method;

/*
 * Parse pretemplates and replace with real templates
 */
public class TemplateParser {

    public static Api parseTemplates(final ApiIndex api, final NTEnv ntEnv) {
        final Api raw = rewriteTemplateVars((Api) api.ast(), ntEnv);
        return (Api) raw.accept(new NodeUpdateVisitor() {
            @Override
            public Node forGrammarDecl(GrammarDecl thatGrammarDecl) {
                if (!thatGrammarDecl.isNativeDef()) {
                    final Class<?> parser = createParser(findGrammar(thatGrammarDecl));
                    return thatGrammarDecl.accept(new NodeUpdateVisitor() {
                        @Override
                        public Node forUnparsedTransformer(UnparsedTransformer that) {
                            AbstractNode templateNode = parseTemplate(raw.getName(),
                                                                      that.getTransformer(),
                                                                      that.getNonterminal(),
                                                                      parser);
                            return new NodeTransformer(templateNode.getInfo(), templateNode);
                        }
                    });
                } else {
                    return thatGrammarDecl;
                }
            }

            private GrammarIndex findGrammar(GrammarDecl grammar) {
                for (GrammarIndex index : api.grammars().values()) {
                    if (index.getName().equals(grammar.getName())) {
                        return index;
                    }
                }
                throw new MacroError("Could not find grammar for " + grammar.getName());
            }
        });
    }

    private static Api rewriteTemplateVars(Api api, final NTEnv ntEnv) {
        return (Api) api.accept(new NodeUpdateVisitor() {
            @Override
            public Node forSyntaxDef(SyntaxDef thatSyntaxDef) {
                final GapEnv gapEnv = EnvFactory.makeGapEnv(thatSyntaxDef, ntEnv);
                Debug.debug(Debug.Type.SYNTAX, 3, "Gap env: ", gapEnv);
                return thatSyntaxDef.accept(new NodeUpdateVisitor() {
                    @Override
                    public Node forNamedTransformerDef(NamedTransformerDef that) {
                        TemplateVarRewriter tvs = new TemplateVarRewriter(gapEnv);
                        Transformer transformer = (Transformer) that.getTransformer().accept(tvs);
                        return new NamedTransformerDef(that.getInfo(),
                                                       that.getName(),
                                                       that.getParameters(),
                                                       transformer);
                    }
                });
            }
        });
    }

    private static Class<?> createParser(GrammarIndex grammar) {
        return ParserMaker.parserForGrammar(grammar);
    }

    private static AbstractNode parseTemplate(APIName apiName, String stuff, Id nonterminal, Class<?> parserClass) {
        try {
            BufferedReader in = Useful.bufferedStringReader(stuff.trim());
            Debug.debug(Debug.Type.SYNTAX, 3, "Parsing template '" + stuff + "' with nonterminal " + nonterminal);
            ParserBase parser = RatsUtil.getParserObject(parserClass, in, NodeUtil.getSpan(apiName).getFileName());
            xtc.parser.Result result = (xtc.parser.Result) invokeMethod(parser, ratsParseMethod(nonterminal));
            if (result.hasValue()) {
                Object node = ((SemanticValue) result).value;
                Debug.debug(Debug.Type.SYNTAX, 2, "Parsed '", stuff, "' as node ", node);
                return (AbstractNode) node;
            } else {
                throw new ParserError((ParseError) result, parser);
            }
        }
        catch (Exception e) {
            throw new MacroError("Could not parse '" + stuff + "'", e);
        }
        finally {
            try {
                Files.rm(ProjectProperties.macroErrorLog(NodeUtil.getSpan(apiName).getFileName() ));
            } catch (IOException e) {}
        }
    }

    private static Object invokeMethod(Object obj, String name) {
        Option<Method> method = lookupExpression(obj.getClass(), name);
        if (method.isNone()) {
            throw new MacroError("Could not find method " + name + " in " + obj.getClass().getName());
        } else {
            try {
                return (xtc.parser.Result) method.unwrap().invoke(obj, 0);
            }
            catch (IllegalAccessException e) {
                throw new MacroError(e);
            }
            catch (java.lang.reflect.InvocationTargetException e) {
                throw new MacroError(e);
            }
        }
    }

    private static Option<Method> lookupExpression(Class<?> parser, String production) {
        try {
            /* This is a Rats! specific naming convention.
             * Move it elsewhere?
             */
            String fullName = production; // for example, "pExprOnly"
            Method found = parser.getDeclaredMethod(fullName, int.class);
            /* method is private by default so we have to make it accessible */
            if (found != null) {
                found.setAccessible(true);
                return Option.wrap(found);
            } else {
                return Option.none();
            }
        }
        catch (NoSuchMethodException e) {
            throw new MacroError(e);
        }
        catch (SecurityException e) {
            throw new MacroError(e);
        }
    }

    private static String ratsParseMethod(Id nonterminal) {
        String str = nonterminal.toString();
        if (str.startsWith("FortressSyntax")) {
            return "p" + str.substring(str.indexOf(".") + 1).replace('.', '$');
        } else {
            return "pUSER_" + str.replace("_", "__").replace('.', '_');
        }
    }
}

package com.sun.fortress.compiler.phases;

import com.sun.fortress.compiler.AnalyzeResult;
import com.sun.fortress.compiler.GlobalEnvironment;
import com.sun.fortress.compiler.StaticChecker;
import com.sun.fortress.exceptions.MultipleStaticError;
import com.sun.fortress.exceptions.StaticError;
import com.sun.fortress.scala_src.typechecker.IndexBuilder;
import com.sun.fortress.useful.Debug;
import edu.rice.cs.plt.collect.CollectUtil;
import edu.rice.cs.plt.iter.IterUtil;
import edu.rice.cs.plt.tuple.Option;

public class TypeCheckPhase extends Phase {

    public TypeCheckPhase(Phase parentPhase) {
        super(parentPhase);
    }

    @Override
    public AnalyzeResult execute() throws StaticError {
        Debug.debug(Debug.Type.FORTRESS, 1, "Start phase TypeCheck");
        AnalyzeResult previous = parentPhase.getResult();

        IndexBuilder.ApiResult apiIndex = IndexBuilder.buildApis(previous.apiIterator(), this.env, lastModified);

        IndexBuilder.ComponentResult componentIndex = IndexBuilder.buildComponents(previous.componentIterator(),
                                                                                   lastModified);

        GlobalEnvironment apiEnv = new GlobalEnvironment.FromMap(CollectUtil.union(env.apis(), apiIndex.apis()));

        StaticChecker.ApiResult apiSR = StaticChecker.checkApis(apiIndex.apis(), apiEnv);

        if (!apiSR.isSuccessful()) {
            throw new MultipleStaticError(apiSR.errors());
        }

        StaticChecker.ComponentResult componentSR = StaticChecker.checkComponents(componentIndex.components(), env);

        if (!componentSR.isSuccessful()) {
            throw new MultipleStaticError(componentSR.errors());
        }

        return new AnalyzeResult(apiSR.apis(),
                                 componentSR.components(),
                                 IterUtil.<StaticError>empty(),componentSR.typeCheckers());
    }

}

